/**
 * Monday.com Node - Version 2
 * Discriminator: resource=group, operation=duplicateGroup
 */


interface Credentials {
  mondayComApi: CredentialReference;
  mondayComOAuth2Api: CredentialReference;
}

/** Create a copy of a group with its items on the same board */
export type MondayComV2GroupDuplicateGroupParams = {
  resource: 'group';
  operation: 'duplicateGroup';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * The group to operate on
 * @searchListMethod searchGroups
 * @default {"mode":"list","value":""}
 */
    groupId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Options
 * @default {}
 */
    duplicateGroupOptions?: {
    /** The title of the new group; left unset, monday derives one from the original
     */
    groupTitle?: string | Expression<string>;
    /** Where to place the duplicated group on the board; left unset, monday puts it right below the original group. Placements other than "At Top" cost one extra repositioning call.
     * @default top
     */
    groupPosition?: 'after' | 'bottom' | 'top' | 'before' | Expression<string>;
    /** The existing group the duplicate is placed before or after (used with Position "After Group" / "Before Group"). Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
     * @loadOptionsMethod getBoardGroups
     * @displayOptions.show { groupPosition: ["after", "before"] }
     */
    positionGroupId?: string | Expression<string>;
  };
/**
 * The board to operate on
 * @searchListMethod searchBoards
 * @default {"mode":"list","value":""}
 */
    boardId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
};

export type MondayComV2GroupDuplicateGroupNode = {
  type: 'n8n-nodes-base.mondayCom';
  version: 2;
  config: NodeConfig<MondayComV2GroupDuplicateGroupParams> & { credentials?: Credentials };
};